double m = 0.5 * (a + b);
double I_whole = (b - a) * f(m);

double m_left  = 0.5 * (a + m);
double m_right = 0.5 * (m + b);
double I_left  = (m - a) * f(m_left);
double I_right = (b - m) * f(m_right);
double I_split = I_left + I_right;

double err = std::fabs(I_split - I_whole) / 3.0;

if (err <= precision) {
    return I_split;
} else {
    // split the tolerance equally between the two sub‑intervals
    double half_prec = precision / 2.0;
    return adaptive_midpoint(f, a, m, half_prec) +
           adaptive_midpoint(f, m, b, half_prec);
}

